// Minimal endless‑runner based on IDEA.md
// Canvas with id "game"
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const width = canvas.width;
  const height = canvas.height;

  // Player (dot)
  const player = { x: 50, y: height / 2, r: 8, speed: 2 };

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key] = true; });
  window.addEventListener('keyup', e => { keys[e.key] = false; });

  // Obstacles and stars
  const obstacles = [];
  const stars = [];
  let frames = 0;
  let score = 0;
  let gameOver = false;

  function spawnObstacle() {
    const size = 12 + Math.random() * 8;
    obstacles.push({ x: width + size, y: Math.random() * (height - size), w: size, h: size, speed: 3 + Math.random() * 2 });
  }
  function spawnStar() {
    const r = 4 + Math.random() * 3;
    stars.push({ x: width + r, y: Math.random() * (height - r), r, speed: 2 });
  }

  function update() {
    if (gameOver) return;
    // player movement
    if (keys.ArrowUp) player.y -= player.speed;
    if (keys.ArrowDown) player.y += player.speed;
    if (keys.ArrowLeft) player.x -= player.speed;
    if (keys.ArrowRight) player.x += player.speed;

    // bounds check – end if outside
    if (player.x < 0 || player.x > width || player.y < 0 || player.y > height) {
      gameOver = true;
    }

    // move obstacles and stars
    obstacles.forEach(o => o.x -= o.speed);
    stars.forEach(s => s.x -= s.speed);
    // remove off‑screen
    obstacles.filter(o => o.x + o.w > 0);
    stars.filter(s => s.x + s.r > 0);
    // collision detection
    for (const o of obstacles) {
      if (player.x + player.r > o.x && player.x - player.r < o.x + o.w &&
          player.y + player.r > o.y && player.y - player.r < o.y + o.h) {
        gameOver = true;
        break;
      }
    }
    for (let i = stars.length - 1; i >= 0; i--) {
      const s = stars[i];
      const dx = player.x - s.x;
      const dy = player.y - s.y;
      if (Math.hypot(dx, dy) < player.r + s.r) {
        score++;
        stars.splice(i, 1);
      }
    }
    // spawn entities
    if (frames % 120 === 0) spawnObstacle();
    if (frames % 180 === 0) spawnStar();
    frames++;
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // player
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.r, 0, Math.PI * 2);
    ctx.fill();
    // obstacles
    ctx.fillStyle = '#f00';
    obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));
    // stars
    ctx.fillStyle = '#ff0';
    stars.forEach(s => {
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
      ctx.fill();
    });
    // score
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
    // game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#fff';
      ctx.font = '24px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

  function loop() {
    update();
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  // start
  requestAnimationFrame(loop);
})();
